# Untrapped Ultra Mode - bounded self-repair engine
# Repairs the Ultra Mode control plane plus the Untrapped browser-extension source and,
# when found, the actual Brave unpacked/installed extension directory. It does not modify
# Windows Firewall, WFP, Winsock, DNS, routes, adapters, VPN, Hosts, or the override policy.
$ErrorActionPreference='Stop'
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path
$ExtensionRoot=Split-Path -Parent $Root
$RepoBase='https://raw.githubusercontent.com/mehdishah5372-hue/Untrapped/main/'
$BackupRoot=Join-Path $Root 'repair-backups';$RepairReport=Join-Path $Root 'repair-success-latest.txt'
$Core=@(
 @{Remote='ultra-mode/packet-filter.ps1';Rel='packet-filter.ps1';Type='script'},@{Remote='ultra-mode/ultra-mode.ps1';Rel='ultra-mode.ps1';Type='script'},@{Remote='ultra-mode/status-untrapped.ps1';Rel='status-untrapped.ps1';Type='script'},@{Remote='ultra-mode/config.json';Rel='config.json';Type='json'}
)
$Ext=@(
 @{Remote='manifest.json';Rel='manifest.json';Type='json'},@{Remote='background.js';Rel='background.js';Type='script'},@{Remote='content.js';Rel='content.js';Type='script'},@{Remote='popup.html';Rel='popup.html';Type='text'},@{Remote='popup.js';Rel='popup.js';Type='script'},@{Remote='bootstrap.bundle.min.js';Rel='bootstrap.bundle.min.js';Type='script'}
)
function Valid([hashtable]$x,[string]$t){if([string]::IsNullOrWhiteSpace($t)){return $false};try{switch($x.Type){'script'{[void][scriptblock]::Create($t);return $true};'json'{$null=$t|ConvertFrom-Json;return $true};default{return $t.Length -gt 20}}}catch{return $false}}
function Download([hashtable]$x){$tmp=Join-Path $env:TEMP ('untrapped-repair-'+[guid]::NewGuid().ToString('N')+'-'+[IO.Path]::GetFileName($x.Rel));Invoke-WebRequest -Uri ($RepoBase+$x.Remote) -OutFile $tmp -UseBasicParsing -TimeoutSec 20 -ErrorAction Stop;$text=[IO.File]::ReadAllText($tmp);if(!(Valid $x $text)){Remove-Item $tmp -Force -ErrorAction SilentlyContinue;throw "Canonical $($x.Rel) failed validation."};return @{Path=$tmp;Text=$text}}
try{
 if(!(Test-Path $BackupRoot)){New-Item -ItemType Directory -Path $BackupRoot -Force|Out-Null};[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
 $stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$changed=$false;$failed=$false;$rl=New-Object System.Collections.Generic.List[string];[void]$rl.Add('UNTRAPPED ULTRA MODE - SELF-REPAIR REPORT');[void]$rl.Add('Time: '+(Get-Date).ToString('yyyy-MM-dd HH:mm:ss zzz'));[void]$rl.Add('')
 function RepairSet([string]$base,$items,[string]$label){foreach($x in $items){$path=Join-Path $base $x.Rel;$need=!(Test-Path $path);if(!$need){try{$need=!(Valid $x ([IO.File]::ReadAllText($path)))}catch{$need=$true}};if(!$need){Write-Host "[OK] $label/$($x.Rel)";continue};Write-Host "[REPAIR NEEDED] $label/$($x.Rel)";[void]$rl.Add("[REPAIR] $label/$($x.Rel)");$tmp=$null;try{$d=Download $x;$tmp=$d.Path;if(Test-Path $path){$backup=Join-Path $BackupRoot ($stamp+'-'+$label.Replace('/','_')+'-'+$x.Rel.Replace('/','_'));Copy-Item $path $backup -Force;[void]$rl.Add('[BACKUP] '+$backup)};Copy-Item $tmp $path -Force;Write-Host "[OK REPAIRED] $label/$($x.Rel)";[void]$rl.Add("[OK REPAIRED] $label/$($x.Rel)");$script:changed=$true}catch{Write-Host "[FAIL REPAIR] $label/$($x.Rel): $($_.Exception.Message)";[void]$rl.Add("[FAIL] $label/$($x.Rel): $($_.Exception.Message)");$script:failed=$true}finally{if($tmp){Remove-Item $tmp -Force -ErrorAction SilentlyContinue}}}}
 RepairSet $ExtensionRoot $Ext 'extension-source';RepairSet $Root $Core 'ultra-mode'
 # Find Brave extension directories whose manifest is specifically Untrapped. This avoids touching unrelated extensions.
 $braveBases=@("$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\Default\Extensions","$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\Profile *\Extensions")
 $installed=@();foreach($pat in $braveBases){$installed+=@(Get-ChildItem -Path $pat -Directory -ErrorAction SilentlyContinue)};$matches=@();foreach($dir in $installed){$mans=@(Get-ChildItem $dir.FullName -Filter manifest.json -Recurse -File -ErrorAction SilentlyContinue);foreach($m in $mans){try{$j=Get-Content $m.FullName -Raw|ConvertFrom-Json;if([string]$j.name -eq 'Untrapped'){$matches+=$m.Directory.FullName}}catch{}}};$matches=@($matches|Select-Object -Unique)
 if($matches.Count){foreach($m in $matches){Write-Host "[FOUND] Brave Untrapped extension: $m";[void]$rl.Add('[FOUND] Brave extension: '+$m);RepairSet $m $Ext 'brave-extension'}}else{Write-Host '[INFO] Brave-installed Untrapped extension not found; source extension was checked/repaired.';[void]$rl.Add('[INFO] No Brave-installed Untrapped extension directory was found.')}
 foreach($native in @('WinDivert.dll','WinDivert64.sys')){if(Test-Path (Join-Path $Root $native)){[void]$rl.Add("[OK] $native present.")}else{[void]$rl.Add("[FAIL] $native missing; native binary not modified.");$failed=$true}}
 if($changed){Write-Host '[RESTART] Reloading Untrapped control plane.';[void]$rl.Add('[RESTART] Reloading control processes.');foreach($pat in @('*packet-filter.ps1*','*ultra-mode.ps1*')){@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|? CommandLine -like $pat)|%{Stop-Process $_.ProcessId -Force -ErrorAction SilentlyContinue}};Start-Sleep -Milliseconds 700;foreach($f in @('packet-filter.ps1','ultra-mode.ps1')){if(Test-Path (Join-Path $Root $f)){Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $Root $f)) -WorkingDirectory $Root -Verb RunAs -WindowStyle Hidden -ErrorAction SilentlyContinue}};[void]$rl.Add('[OK] Control restart issued.')}
 if($failed){[void]$rl.Add('');[void]$rl.Add('[FAIL] Self-repair did not complete successfully.');$rl|Set-Content $RepairReport -Encoding UTF8;Start-Process notepad.exe -ArgumentList $RepairReport -ErrorAction SilentlyContinue;exit 1}
 [void]$rl.Add('');[void]$rl.Add($(if($changed){'[SUCCESS] Untrapped and extension repair completed successfully.'}else{'[HEALTHY] No repair required.'}));$rl|Set-Content $RepairReport -Encoding UTF8;if($changed){Start-Process notepad.exe -ArgumentList $RepairReport -ErrorAction SilentlyContinue};exit 0
}catch{try{@('UNTRAPPED SELF-REPAIR FAILURE','Time: '+(Get-Date).ToString('yyyy-MM-dd HH:mm:ss zzz'),'[FAIL] '+$_.Exception.Message)|Set-Content $RepairReport -Encoding UTF8;Start-Process notepad.exe -ArgumentList $RepairReport -ErrorAction SilentlyContinue}catch{};exit 1}
